#[cfg(test)]mod fused_scale_consumer_tests{
 use super::*;
 #[test]fn complete_scaled_numerator_all_sign_masks(){
  let mut state=0x66757365642d6732u64;let mut random=||{loop{let words=core::array::from_fn(|j|{state^=state<<13;state^=state>>7;state^=state<<17;if j==3{state&((1u64<<62)-1)}else{state}});if let Some(f)=Fq::from_canonical(words){break f;}}};
  let mut by:[Fq2;LANES]=core::array::from_fn(|_|Fq2::new(random(),random()));let mut ay:[Fq2;LANES]=core::array::from_fn(|_|Fq2::new(random(),random()));let bx:[Fq2;LANES]=core::array::from_fn(|_|Fq2::new(random(),random()));let ax:[Fq2;LANES]=core::array::from_fn(|_|Fq2::new(random(),random()));let scale:[Fq;LANES]=core::array::from_fn(|_|random());let second:[Fq;LANES]=core::array::from_fn(|_|random());by[0]=Fq2::ZERO;ay[0]=Fq2::ZERO;
  let denominator=core::array::from_fn(|j|fq2_pack(bx)[j].sub_canonical(&fq2_pack(ax)[j]));let factor=FqBatch::new(&scale).mul(&FqBatch::new(&second));
  for mask in 0..=255u8{let py=fq2_pack(by);let pa=fq2_pack(ay);let dy=core::array::from_fn(|j|py[j].signed_difference_canonical(&pa[j],mask));let got=fq2_unpack(Fq2::lanes_scaled_numerator(&dy,&denominator,&factor));for i in 0..LANES{let y=if mask&(1<<i)!=0{-by[i]}else{by[i]};let expected=((y-ay[i])*(bx[i]-ax[i]).conjugate()).mul_by_fp(&(scale[i]*second[i]));assert_eq!(got[i],expected);}for i in 1..LANES{by[i]=got[i];}}
  println!("FUSED_SCALE_CORE fullwidth_complex_outputs=2048 sign_masks=256 negative_zero_lane=true output_fed=true");
 }
}

